// #6490: switch OFF (and the uncontacted b2 cadence read) are proven against FROZEN merge-base
// output (#7587). The fixtures were generated by the merge-base code in a separate checkout; they
// are never regenerated with the new code. See the fixture files for the merge-base SHA.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { PGlite } from "@electric-sql/pglite";
import * as peak from "./racePeakPlans.js";
import { runOffScenarios, buildScenario } from "./__fixtures__/peakLeadup6490OffScenarios.js";
import { CADENCE_CASES } from "./__fixtures__/dailyConditionCadence6490Cases.js";
import {
  evaluateTrainingHistoryFromTicksFlag, TRAINING_HISTORY_FROM_TICKS_6490_FLAG_KEY, TRAINING_PEAK_FROM_TICKS_6490_FLAG_KEY,
} from "./trainingHistoryFromTicks6490.js";

const json = (name) => JSON.parse(readFileSync(new URL(`./__fixtures__/${name}`, import.meta.url), "utf8"));
const PEAK_BASE = json("peakLeadup6490OffBase.json");
const CADENCE_BASE = json("dailyConditionCadence6490Base.json");

test("the fixtures come from one merge-base and the scenarios exercise real windows", () => {
  assert.match(PEAK_BASE.mergeBase, /^[0-9a-f]{40}$/);
  assert.equal(CADENCE_BASE.mergeBase, PEAK_BASE.mergeBase);
  const s = buildScenario(1);
  assert.ok(s.rows.length > 100 && s.windows.size > 3, "a non-trivial scenario");
});

for (const flag of [null, "off", "beta", true, "ON", "on "]) {
  test(`trin c off (${JSON.stringify(flag)}): peak qualities and riderMaps are bit-identical with the merge-base`, async () => {
    assert.equal(evaluateTrainingHistoryFromTicksFlag(flag), false);
    assert.deepEqual(await runOffScenarios(peak, { flag }), PEAK_BASE.results);
  });
}

// Fable-dom 15/11, fund 1: the training page's switch (history "on") never reaches the motor input.
// With the peak signal's own switch off, the output is still the merge-base's, bit for bit.
for (const peakFlag of [null, "off", "beta"]) {
  test(`trin c: peak switch ${JSON.stringify(peakFlag)} with the history switch "on" is bit-identical with the merge-base`, async () => {
    const flags = { [TRAINING_HISTORY_FROM_TICKS_6490_FLAG_KEY]: "on", [TRAINING_PEAK_FROM_TICKS_6490_FLAG_KEY]: peakFlag };
    assert.deepEqual(await runOffScenarios(peak, { flags }), PEAK_BASE.results);
  });
}

test("b2: the cadence guard gives the merge-base answer for every stored report shape", async () => {
  const src = readFileSync(new URL("./dailyTrainingEngine.js", import.meta.url), "utf8");
  assert.ok(src.includes(".select('game_day, tick_date, condition_per_date:report->condition_per_date')"), "the new select");
  const GUARD = "if((dateRuns??[]).some(row=>row.condition_per_date!==true)) throw new Error('Cannot switch condition cadence during a partially executed date');";
  assert.ok(src.includes(GUARD), "the new guard");
  const guard = new Function("dateRuns", `${GUARD} return false;`);
  const db = new PGlite();
  try {
    await db.exec("CREATE TABLE r(c integer, n integer, game_day integer, tick_date date, report jsonb NOT NULL)");
    const results = [];
    for (let c = 0; c < CADENCE_CASES.length; c++) {
      for (let n = 0; n < CADENCE_CASES[c].length; n++) {
        await db.query("INSERT INTO r VALUES($1,$2,$3,'2026-11-09',$4::jsonb)", [c, n, 41 + n, JSON.stringify(CADENCE_CASES[c][n])]);
      }
      // PostgREST's `condition_per_date:report->condition_per_date` is `report->'condition_per_date'`.
      const { rows } = await db.query("SELECT game_day, tick_date, report->'condition_per_date' AS condition_per_date FROM r WHERE c=$1 ORDER BY n", [c]);
      let throws = false;
      try { guard(rows); } catch { throws = true; }
      results.push({ case: c, throws });
    }
    assert.deepEqual(results, CADENCE_BASE.results);
  } finally {
    await db.close();
  }
});
